const explicitIntentSubjectTerms = (shot) => {
  const text=String(shot.visual_intent || '').trim().replace(/^show(?:ing)?\s+/i,'');
  const match=text.match(/^(?:a|an|the)\s+(.+?)(?=\s+(?:[a-z]+ing|stands?|sits?|is|are|near|beside|inside|outside|within|with|at|on|in|against)\b|[.,;]|$)/i);
  if (!match || match[1].trim().split(/\s+/).length > 5) return [];
  const words=contextTokens(match[1]);
  const anchors=contextTokens((shot.must_show || []).join(' '));
  const singular=word=>word.replace(/s$/,'');
  if (words.some(word=>anchors.some(anchor=>singular(word)===singular(anchor)))) return [];
  const generic=new Set('view closeup photograph photo image picture scene detail structure building process flow result action'.split(' '));
  return words.filter(word=>!generic.has(word) && !localContextNoise.has(word) && !processOutputDomainNoise.has(word));
};

const primaryContextKey = value => {
  const tokens = contextTokens(value);
  return tokens.length
    ? tokens.join(' ')
    : String(value || '').trim().toLowerCase();
};

const primaryCounts = new Map();
for (const shot of shots) {
  const mustShow = Array.isArray(shot.must_show) ? shot.must_show.map(String) : [];
  const primaryKey = primaryContextKey(mustShow[0]);
  if (primaryKey) {
    primaryCounts.set(primaryKey, (primaryCounts.get(primaryKey) || 0) + 1);
  }
}

// Repeated machinery/closed-infrastructure subjects may inherit a shared
// operating domain learned elsewhere in the storyboard (for example
// domain-qualified generators). Generic objects must not inherit this hard gate:
// otherwise unrelated repeated vocabulary can turn terms such as module/RAM
// into mandatory context for a plain circuit-board shot.
const qualifierShots = new Map();
for (const shot of shots) {
  const ownAnchors = new Set(contextTokens((shot.must_show || []).join(' ')));
  const qualifiers = contextTokens((shot.queries_en || []).slice(0,2).join(' '))
    .filter(t => !ownAnchors.has(t));
  for (const term of qualifiers) {
    if (!qualifierShots.has(term)) qualifierShots.set(term,new Set());
    qualifierShots.get(term).add(String(shot.shot_uuid));
  }
}
const primaryDomainTerms = new Map();
for (const shot of shots) {
  const primaryTokens = contextTokens((shot.must_show || [])[0]);
  const primaryHead = primaryTokens.length ? primaryTokens[primaryTokens.length - 1] : '';
  if (!domainScopedHeads.has(primaryHead)) continue;
  const key = primaryContextKey((shot.must_show || [])[0]);
  if (Number(primaryCounts.get(key) || 0) < 2) continue;
  const qualifiers = contextTokens((shot.queries_en || []).slice(0,2).join(' '))
    .filter(term =>
      !processOutputDomainNoise.has(term) &&
      (qualifierShots.get(term)?.size || 0) >= 2
    );
  if (!primaryDomainTerms.has(key)) primaryDomainTerms.set(key,new Set());
  for (const term of qualifiers) primaryDomainTerms.get(key).add(term);
}

const operatingSettingTokens = value => new Set(
  String(value || '').toLowerCase().replace(/[^a-z0-9]+/g,' ').split(/\s+/)
    .filter((term) => ['plant','station','facility','powerhouse','factory','site'].includes(term))
);
const sharesOperatingSetting = (left,right) => {
  const a=operatingSettingTokens(left);
  const b=operatingSettingTokens(right);
  return [...a].some((term) => b.has(term));
};

// Compute only each shot's OWN explicit/repeated domain first. This lets a
// closed infrastructure shot inherit a domain from an immediately adjacent
// domain-scoped shot in the same operating setting without depending on order.
const directDomainBySceneOrder = new Map();
const shotBySceneOrder = new Map();
for (const candidateShot of shots) {
  const candidateMustShow = Array.isArray(candidateShot.must_show)
    ? candidateShot.must_show.map(String)
    : [];
  const candidatePrimaryKey = primaryContextKey(candidateMustShow[0]);
  const candidatePrimaryTokens = contextTokens(candidateMustShow[0]);
  const candidatePrimaryHead = candidatePrimaryTokens.length
    ? candidatePrimaryTokens[candidatePrimaryTokens.length - 1]
    : '';
  const candidateOwnPrimary = new Set(candidatePrimaryTokens);
  const candidatePlannedQualifiers = contextTokens(
    (candidateShot.queries_en || []).slice(0,2).join(' ')
  );
  const candidateLocal = domainScopedHeads.has(candidatePrimaryHead)
    ? contextTokens(candidateShot.visual_intent)
        .filter((term) =>
          !candidateOwnPrimary.has(term) &&
          candidatePlannedQualifiers.some((planned) => sameDomainTerm(term,planned)) &&
          !localContextNoise.has(term) &&
          !processOutputDomainNoise.has(term) &&
          !domainScopedHeads.has(term) &&
          !(
            closedInfrastructureHeads.has(candidatePrimaryHead) &&
            closedInfrastructureMediumTerms.has(term)
          )
        )
        .sort((a,b) => b.length - a.length || a.localeCompare(b))[0] || ''
    : '';
  const candidateRepeated = [...new Set(
    [...(primaryDomainTerms.get(candidatePrimaryKey) || [])]
  )].filter((term) =>
    !(
      closedInfrastructureHeads.has(candidatePrimaryHead) &&
      closedInfrastructureMediumTerms.has(term)
    )
  );
  const candidateSceneOrder = Number(candidateShot.scene_order);
  if (Number.isFinite(candidateSceneOrder)) {
    shotBySceneOrder.set(candidateSceneOrder,candidateShot);
    const explicit = explicitSettingTerms(candidateShot,candidateOwnPrimary,candidatePlannedQualifiers)
      .sort((a,b) => b.length-a.length || a.localeCompare(b))[0];
    const direct = explicit || candidateLocal || candidateRepeated[0] || '';
    if (direct) directDomainBySceneOrder.set(candidateSceneOrder,direct);
  }
}

const out = [];
let previousMachineryDomain = '';
let previousMachinerySceneOrder = null;
for (const shot of shots) {
  const queries = Array.isArray(shot.queries_en) ? shot.queries_en : [];
  if (!queries.length) throw new Error('M8 shot has no visual queries: ' + String(shot.shot_key || 'unknown'));

  const mustShow = Array.isArray(shot.must_show) ? shot.must_show.map(String) : [];
  const primaryKey = primaryContextKey(mustShow[0]);
  const primaryRepeated = primaryKey
    ? Number(primaryCounts.get(primaryKey) || 0) > 1
    : false;
  const secondaryFallback = String(mustShow[1] || '').trim();
  const primaryTokens = contextTokens(mustShow[0]);
  const primaryHead = primaryTokens.length ? primaryTokens[primaryTokens.length - 1] : '';
  const ownPrimaryTerms = new Set(primaryTokens);
  const plannedQualifierTerms = contextTokens(
    (shot.queries_en || []).slice(0,2).join(' ')
  );
  const localCandidates = domainScopedHeads.has(primaryHead)
    ? contextTokens(shot.visual_intent)
        .filter((term) =>
          !ownPrimaryTerms.has(term) &&
          plannedQualifierTerms.some((planned) => sameDomainTerm(term,planned)) &&
          !localContextNoise.has(term) &&
          !processOutputDomainNoise.has(term) &&
          !domainScopedHeads.has(term) &&
          !(
            closedInfrastructureHeads.has(primaryHead) &&
            closedInfrastructureMediumTerms.has(term)
          )
        )
    : [];
  localCandidates.push(...explicitSettingTerms(shot,ownPrimaryTerms,plannedQualifierTerms));
  localCandidates.push(...explicitIntentSubjectTerms(shot));
  const localDomainTerm =
    localCandidates.sort((a,b) => b.length - a.length || a.localeCompare(b))[0] || '';
  const repeatedDomainTerms = [...new Set(
    [...(primaryDomainTerms.get(primaryKey) || [])]
  )].filter((term) =>
    !(
      closedInfrastructureHeads.has(primaryHead) &&
      closedInfrastructureMediumTerms.has(term)
    )
  );
  const sceneOrder = Number(shot.scene_order);
  const inheritedDomainTerm =
    machineryHeads.has(primaryHead) &&
    !localDomainTerm &&
    repeatedDomainTerms.length === 0 &&
    previousMachineryDomain &&
    Number.isFinite(sceneOrder) &&
    Number.isFinite(previousMachinerySceneOrder) &&
    sceneOrder === previousMachinerySceneOrder + 1
      ? previousMachineryDomain
      : '';

  const adjacentInfrastructureDomains = [];
  if (
    closedInfrastructureHeads.has(primaryHead) &&
    !localDomainTerm &&
    repeatedDomainTerms.length === 0 &&
    Number.isFinite(sceneOrder)
  ) {
    for (const neighborOrder of [sceneOrder - 1, sceneOrder + 1]) {
      const neighborShot = shotBySceneOrder.get(neighborOrder);
      const neighborDomain = directDomainBySceneOrder.get(neighborOrder);
      if (
        neighborShot &&
        neighborDomain &&
        sharesOperatingSetting(shot.visual_intent,neighborShot.visual_intent)
      ) {
        adjacentInfrastructureDomains.push(neighborDomain);
      }
    }
  }
  const uniqueAdjacentInfrastructureDomains =
    [...new Set(adjacentInfrastructureDomains)];
  const adjacentInfrastructureDomainTerm =
    uniqueAdjacentInfrastructureDomains.length === 1
      ? uniqueAdjacentInfrastructureDomains[0]
      : '';

  const domainTerms = [...new Set([
    ...repeatedDomainTerms,
    ...(localDomainTerm ? [localDomainTerm] : []),
    ...(inheritedDomainTerm ? [inheritedDomainTerm] : []),
    ...(adjacentInfrastructureDomainTerm ? [adjacentInfrastructureDomainTerm] : []),
  ])].sort();

  const detailTokenKey = (value) => {
    let term=String(value || '').toLowerCase();
    if (term.endsWith('ies') && term.length > 5) return term.slice(0,-3) + 'y';
    if (term.endsWith('s') && term.length > 3 && !term.endsWith('ss')) {
      term=term.slice(0,-1);
    }
    return term;
  };
  const firstQueryDetailTerms = new Set(
    contextTokens(queries[0] || '').map(detailTokenKey)
  );
  const ownMustShowTerms = new Set(
    contextTokens(mustShow.join(' ')).map(detailTokenKey)
  );
  const primaryHeadKey=detailTokenKey(primaryHead);
  const primaryIsMachinery=machineryHeads.has(primaryHeadKey);
  const primaryIsClosedInfrastructure=closedInfrastructureHeads.has(primaryHeadKey);
  const intentDetailTokens=contextTokens(shot.visual_intent).map(detailTokenKey);
  const hasExplicitMotionIntent=intentDetailTokens.some(
    (term) => visualDetailMotionTerms.has(term)
  );
  const rawVisualDetailTerms=[...new Set(
    intentDetailTokens.filter((term) =>
      firstQueryDetailTerms.has(term) &&
      !ownMustShowTerms.has(term) &&
      visualDetailComponentTerms.has(term) &&
      !(
        primaryIsClosedInfrastructure &&
        closedInfrastructureHeads.has(term)
      ) &&
      !domainTerms.some((domainTerm) => sameDomainTerm(term,domainTerm))
    )
  )].sort();
  const enforceVisualDetails =
    rawVisualDetailTerms.length >= 2 ||
    (
      !primaryIsMachinery &&
      !primaryIsClosedInfrastructure &&
      rawVisualDetailTerms.length >= 1
    ) ||
    (
      primaryIsMachinery &&
      hasExplicitMotionIntent &&
      rawVisualDetailTerms.length >= 1
    );
  const visualDetailTerms=enforceVisualDetails
    ? rawVisualDetailTerms
    : [];

  if (machineryHeads.has(primaryHead)) {
    previousMachineryDomain =
      localDomainTerm ||
      repeatedDomainTerms[0] ||
      inheritedDomainTerm ||
      '';
    previousMachinerySceneOrder = sceneOrder;
  } else {
    previousMachineryDomain = '';
    previousMachinerySceneOrder = null;
  }

  for (let i=0;i<queries.length;i++) {
    const query = String(queries[i] || '').trim();
    if (!query) throw new Error('M8 empty visual query');

    const queryTokens = new Set(contextTokens(query));
    const missingDomainTerms = domainTerms.filter((term) =>
      ![...queryTokens].some((queryTerm) => sameDomainTerm(term,queryTerm))
    );
    // Enrich only the bare machinery fallback; retain storyboard provenance.
    const phraseKey = value => String(value || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
    const rawPhraseTokens = value => phraseKey(value).split(/\s+/).filter(Boolean);
    const queryContextTerms = new Set(contextTokens(query));
    const primaryQueryTerms = contextTokens(mustShow[0]);
    const primaryRepresented =
      primaryQueryTerms.length === 0 ||
      primaryQueryTerms.every((term) => queryContextTerms.has(term));
    const queryMatchesSecondaryFallback = mustShow.slice(1).some(
      (phrase) => phraseKey(phrase) === phraseKey(query)
    );
    const missingPrimaryPhrase =
      mustShow.length > 1 &&
      !primaryRepresented &&
      (machineryHeads.has(primaryHead) || queryMatchesSecondaryFallback)
        ? String(mustShow[0] || '').trim()
        : '';

    // A multi-object machinery fallback may omit the primary subject. Restore
    // it only in provider_query and reuse one specific qualifier from the
    // scene's first (most specific) query. The qualifier remains retrieval
    // context only; it is not promoted to a hard scorer domain.
    const ownAnchorTerms = new Set(contextTokens(mustShow.join(' ')));
    const retrievalQualifierNoise = new Set([
      ...localContextNoise,
      'hall','building','site','area','factory','facility','station','plant',
    ]);
    const firstQueryQualifiers = missingPrimaryPhrase && machineryHeads.has(primaryHead)
      ? contextTokens((shot.queries_en || [])[0] || '')
          .filter((term) =>
            !ownAnchorTerms.has(term) &&
            !retrievalQualifierNoise.has(term) &&
            !domainScopedHeads.has(term)
          )
      : [];
    const fallbackQualifier = firstQueryQualifiers
      .sort((a,b) => b.length - a.length || a.localeCompare(b))[0] || '';

    const bareMachinery = machineryHeads.has(primaryHead) && phraseKey(query) === phraseKey(mustShow[0]);
    const mustShowMachineryHeads = [...new Set(
      mustShow
        .map((phrase) => {
          const phraseTerms=contextTokens(phrase);
          return phraseTerms.length ? phraseTerms[phraseTerms.length - 1] : '';
        })
        .filter((head) => machineryHeads.has(head))
    )];
    const pairedMachineryRetrievalTerms =
      mustShowMachineryHeads.length >= 2
        ? [...mustShowMachineryHeads,'unit']
        : [];

    const intentPhrase=phraseKey(shot.visual_intent);
    const intentRawTokens=rawPhraseTokens(shot.visual_intent);
    const hasProcessOutputIntent=[...processOutputDomainNoise].some(
      (term) => intentRawTokens.includes(term)
    );
    const hasInteriorIntent=
      primaryRepeated &&
      hasProcessOutputIntent &&
      /\b(?:inside|interior)\b/.test(intentPhrase);
    const operatingLocationHeads=['powerhouse','plant','station','facility','factory'];
    const intentLocationHead=hasInteriorIntent
      ? operatingLocationHeads.find((head) => intentRawTokens.includes(head)) || ''
      : '';
    const interiorRetrievalTerms=intentLocationHead
      ? [intentLocationHead,'interior']
      : [];

    const providerBaseTokens = new Set(rawPhraseTokens(
      [
        ...missingDomainTerms,
        fallbackQualifier,
        missingPrimaryPhrase,
        query,
      ].join(' ')
    ));
    const providerBaseDetailKeys = new Set(
      [...providerBaseTokens].map(detailTokenKey)
    );
    const isBroadFinalFallback =
      i === queries.length - 1 &&
      phraseKey(query) === phraseKey(mustShow[0]);
    const containedPrimaryFallback =
      isBroadFinalFallback &&
      /\binside\s+(?:(?:a|an|the)\s+)?[^,.;]+/i.test(String(shot.visual_intent || '')) &&
      (() => {
        const match=String(shot.visual_intent || '').match(
          /\binside\s+(?:(?:a|an|the)\s+)?([^,.;]+)/i
        );
        const phrase=String(match?.[1] || '').split(
          /\b(?:with|containing|showing|displaying|holding|which|that)\b/i
        )[0];
        const tokens=contextTokens(phrase);
        const head=tokens.length ? tokens[tokens.length-1] : '';
        return containmentDetailHeads.has(head);
      })();
    // Preserve the primary-subject fallback as a broad retrieval query.
    // Visual detail requirements remain enforced by metadata and Gemini review.
    const instrumentHeads = new Set([
      'barometer','thermometer','manometer','hygrometer','microscope',
      'telescope','voltmeter','ammeter','altimeter','speedometer',
      'oscilloscope','spectrometer','seismograph','gauge','meter',
    ]);
    const broadInstrumentFallback = isBroadFinalFallback &&
      instrumentHeads.has(primaryHead);
    const missingVisualDetailTerms = containedPrimaryFallback || broadInstrumentFallback
      ? []
      : visualDetailTerms.filter(
          (term) => !providerBaseDetailKeys.has(detailTokenKey(term))
        );
    const contextualLocationHeads = new Set(
      'station plant facility site factory building room lab laboratory area'.split(' ')
    );
    const missingSecondaryPhrases = bareMachinery && !primaryRepeated
      ? mustShow.slice(1)
          .map(String)
          .filter(Boolean)
          .filter((phrase) => {
            const phraseTokens = rawPhraseTokens(phrase);
            const head = phraseTokens.length ? phraseTokens[phraseTokens.length - 1] : '';
            if (contextualLocationHeads.has(head)) return false;
            return phraseTokens.some((term) => !providerBaseTokens.has(term));
          })
      : [];
    const normalizeRetrievalPhrase = value => {
      const normalized=String(value || '')
        .replace(/\bresidential\s+homes?\b/gi,'residential houses')
        .replace(/\s+/g,' ')
        .trim();
      const seen=new Set();
      return normalized.split(/\s+/).filter((token) => {
        const key=token.toLowerCase();
        if (!key || seen.has(key)) return false;
        seen.add(key);
        return true;
      }).join(' ');
    };
    const missingPairedMachineryRetrievalTerms =
      pairedMachineryRetrievalTerms.filter(
        (term) => !providerBaseTokens.has(term)
      );
    const missingInteriorRetrievalTerms =
      interiorRetrievalTerms.filter(
        (term) => !providerBaseTokens.has(term)
      );
    // Commons search is sparse for hidden/internal details and small visual
    // subfeatures whose wording is rarely present in file metadata. For those
    // final secondary-only fallbacks, retrieve the primary subject broadly
    // while retaining every must_show requirement for metadata/Gemini gates.
    // Independent co-subjects (for example houses beside power lines) stay in
    // the provider query and are not broadened away.
    const internalDetailFallbackIntent =
      /\b(?:internal|inside|interior|open|opened|exposed|revealing|cutaway)\b/i
        .test(String(shot.visual_intent || ''));
    const secondaryFallbackTokens = rawPhraseTokens(query);
    const secondaryFallbackHead = secondaryFallbackTokens.length
      ? secondaryFallbackTokens[secondaryFallbackTokens.length - 1]
      : '';
    const visualSubfeatureHeads = new Set([
      'scale','dial','pointer','needle','marking','markings','tube','column',
      'capsule','lever','levers','gear','gears','mechanism'
    ]);
    const visualSubfeatureFallback =
      queryMatchesSecondaryFallback &&
      visualSubfeatureHeads.has(secondaryFallbackHead);
    const usePrimaryOnlySecondaryFallback =
      i === queries.length - 1 &&
      queryMatchesSecondaryFallback &&
      mustShow.length > 1 &&
      (internalDetailFallbackIntent || visualSubfeatureFallback) &&
      !machineryHeads.has(primaryHead) &&
      !closedInfrastructureHeads.has(primaryHead) &&
      String(mustShow[0] || '').trim();

    // A compound detail anchor (camera housing, stapler magazine) names
    // its concrete owner. Commons captions commonly name only that owner.
    // Broaden only the existing internal-detail final fallback; never alter
    // the planned query, required visible concepts or independent subjects.
    const ownedComponentHeads = new Set([
      'magazine','housing','chamber','compartment','cover','handle','arm',
      'blade','base','guide','reservoir'
    ]);
    const ownerMaterialNoise = new Set([
      'paper','metal','steel','plastic','glass','wood','water','oil','gas',
      'air','fuel','spring','internal','inner','outer','fixed','movable'
    ]);
    const primaryRawTerms = rawPhraseTokens(mustShow[0]);
    const ownerPrefix = primaryRawTerms.slice(0,-1);
    // A placement/size qualifier can hide an exposed owner in sparse captions.
    // Broaden only the final single-subject internal-view query; the qualifier
    // remains a mandatory pixel-level requirement in the unchanged contract.
    const ownerPlacementQualifiers = new Set(['desktop','tabletop','handheld','portable']);
    const qualifiedOwnerTerms = primaryRawTerms.filter(term => !ownerPlacementQualifiers.has(term));
    const qualifiedOwnerQuery =
      i === queries.length - 1 &&
      mustShow.length === 1 &&
      internalDetailFallbackIntent &&
      phraseKey(query) === phraseKey(mustShow[0]) &&
      primaryRawTerms.length >= 2 && primaryRawTerms.length <= 3 &&
      qualifiedOwnerTerms.length > 0 &&
      qualifiedOwnerTerms.length < primaryRawTerms.length &&
      domainTerms.length === 0 &&
      !machineryHeads.has(primaryHead) &&
      !closedInfrastructureHeads.has(primaryHead)
        ? qualifiedOwnerTerms.join(' ')
        : '';
    const componentOwnerQuery = qualifiedOwnerQuery || (
      usePrimaryOnlySecondaryFallback &&
      internalDetailFallbackIntent &&
      primaryRawTerms.length >= 2 &&
      primaryRawTerms.length <= 4 &&
      ownedComponentHeads.has(primaryRawTerms[primaryRawTerms.length-1]) &&
      ownerPrefix.some(term => !ownerMaterialNoise.has(term))
        ? ownerPrefix.join(' ')
        : '');

    // Compress only the final independent-object fallback. Material modifiers
    // and quantity nouns rarely occur in Commons captions; original concepts
    // remain mandatory for pixel validation.
    const compactMaterials = new Set('metal steel copper plastic wooden glass rubber'.split(' '));
    const quantityHeads = new Set('sheet sheets piece pieces fragment fragments stack stacks pile piles'.split(' '));
    const compactAnchor = phrase => {
      const tokens=rawPhraseTokens(phrase);
      if (tokens.length>1 && quantityHeads.has(tokens[tokens.length-1])) tokens.pop();
      while (tokens.length>1 && compactMaterials.has(tokens[0])) tokens.shift();
      return tokens.join(' ');
    };
    const pairedCompactAnchors =
      i===queries.length-1 && queryMatchesSecondaryFallback &&
      mustShow.length>1 && !usePrimaryOnlySecondaryFallback &&
      !machineryHeads.has(primaryHeadKey) &&
      !closedInfrastructureHeads.has(primaryHeadKey) &&
      domainTerms.length===0
        ? mustShow.map(compactAnchor)
        : [];
    // A visible deformed subfeature can have sparse captions naming only
    // its owner and the surface. Retrieve both physical objects together;
    // never remove the original surface, shape or orientation requirements.
    const deformedSubfeature = String(shot.visual_intent || '').match(
      /\b(?:showing|with)\s+(?:bent|curved|folded|blunt|sharp|rounded)\s+([a-z]+(?:\s+[a-z]+)?)\s+(?:ends?|tips?|edges?|heads?)\b/i
    );
    const subfeatureOwner = deformedSubfeature ? deformedSubfeature[1].toLowerCase() : '';
    const compactSurface = compactAnchor(mustShow[0]);
    const surfaceHeads = new Set(['paper','sheet','sheets','cloth','fabric','panel','panels','plank','planks']);
    const surfaceOwnerPair =
      i === queries.length - 1 && mustShow.length <= 2 &&
      (mustShow.length === 1 || phraseKey(mustShow[1]) === phraseKey(subfeatureOwner)) &&
      (phraseKey(query) === phraseKey(mustShow[0]) ||
        (rawPhraseTokens(query).every(term=>primaryRawTerms.includes(term) || rawPhraseTokens(subfeatureOwner).includes(term)) &&
         rawPhraseTokens(subfeatureOwner).every(term=>rawPhraseTokens(query).includes(term)))) &&
      surfaceHeads.has(primaryRawTerms.at(-1)) &&
      domainTerms.length === 0 && subfeatureOwner && compactSurface &&
      phraseKey(subfeatureOwner) !== phraseKey(compactSurface) &&
      queries.slice(0,2).some(q => rawPhraseTokens(subfeatureOwner).every(
        term => rawPhraseTokens(q).includes(term)))
        ? [compactSurface,subfeatureOwner] : [];
    const pairedCompactQuery = surfaceOwnerPair.length
      ? [...surfaceOwnerPair].reverse().map(anchor=>rawPhraseTokens(anchor).map(detailTokenKey).join(' ')).join(' ')
      : pairedCompactAnchors.length &&
      pairedCompactAnchors.every(Boolean) &&
      pairedCompactAnchors.some((anchor,index)=>anchor!==phraseKey(mustShow[index]))
        ? pairedCompactAnchors.map(anchor=>rawPhraseTokens(anchor).map(detailTokenKey).join(' ')).join(' ')
        : '';

    const providerQuery = qualifiedOwnerQuery
      ? normalizeRetrievalPhrase(qualifiedOwnerQuery)
      : pairedCompactQuery
      ? normalizeRetrievalPhrase(pairedCompactQuery)
      : usePrimaryOnlySecondaryFallback
      ? normalizeRetrievalPhrase([
          ...missingDomainTerms,
          componentOwnerQuery || String(mustShow[0] || '').trim(),
        ].filter(Boolean).join(' '))
      : normalizeRetrievalPhrase([
          ...missingDomainTerms,
          fallbackQualifier,
          missingPrimaryPhrase,
          ...interiorRetrievalTerms,
          query,
          ...missingPairedMachineryRetrievalTerms,
          ...missingVisualDetailTerms,
          ...missingSecondaryPhrases,
          ...(
            bareMachinery &&
            missingSecondaryPhrases.length === 0 &&
            interiorRetrievalTerms.length === 0
              ? ['equipment']
              : []
          ),
        ].filter(Boolean).join(' '));
    if (!providerQuery) throw new Error('M8 effective provider query is empty');

    out.push({
      json:{
        visual_run_id:String(begin.visual_run_id),
        shot_uuid:String(shot.shot_uuid),
        shot_key:String(shot.shot_key),
        scene_order:Number(shot.scene_order),
        query_index:i+1,
        query,
        provider_query:providerQuery,
        component_owner_query:componentOwnerQuery,
        paired_compact_anchors:pairedCompactQuery ? (surfaceOwnerPair.length ? surfaceOwnerPair : pairedCompactAnchors) : [],
        ...(surfaceOwnerPair.length ? {surface_owner_pair:true} : {}),
        provider:'wikimedia',
        endpoint_kind:String(shot.preferred_media_type) === 'video' ? 'video' : 'photo',
        preferred_media_type:String(shot.preferred_media_type),
        visual_intent:String(shot.visual_intent || ''),
        must_show:mustShow,
        must_not_show:Array.isArray(shot.must_not_show) ? shot.must_not_show : [],
        primary_repeated:primaryRepeated,
        domain_context_terms:domainTerms,
        visual_detail_terms:visualDetailTerms,
        retrieval_structure_terms:[
          ...pairedMachineryRetrievalTerms,
          ...interiorRetrievalTerms,
        ],
      }
    });
  }
}
return out;

baseline_normalizer:
const STOP = new Set([
  'the','and','for','with','from','into','onto','over','under','this','that','these','those',
  'show','showing','display','displaying','view','close','macro','image','photo','video','scene',
  'a','an','of','to','in','on','at','as','by','is','are','be','or'
]);

function stem(token) {
  let t = String(token || '').toLowerCase().replace(/^'+|'+$/g,'');
  if (t === 'houses') return 'house';
  if (t.endsWith('ies') && t.length > 5) return t.slice(0,-3) + 'y';
  if (t.endsWith('ing') && t.length > 6) {
    t = t.slice(0,-3);
    if (/([bcdfghjklmnpqrstvwxyz])\1$/.test(t)) t=t.slice(0,-1);
    return t;
  }
  if (t.endsWith('ed') && t.length > 5) {
    t=t.slice(0,-2);
    if (/([bcdfghjklmnpqrstvwxyz])\1$/.test(t)) t=t.slice(0,-1);
    return t;
  }
  if (/(?:ses|xes|zes|ches|shes)$/.test(t) && t.length > 5) return t.slice(0,-2);
  if (t.endsWith('s') && t.length > 3 && !t.endsWith('ss')) return t.slice(0,-1);
  return t;
}

function tokenSequence(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g,' ')
    .split(/\s+/)
    .map(stem)
    .filter((t) => t.length >= 2 && !STOP.has(t));
}

function terms(value) {
  return [...new Set(tokenSequence(value))];
}

const GENERIC_OBJECT_EQUIVALENTS = [
  ['device','equipment','receiver','instrument','unit','apparatus'],
];

function expandGenericObjectEquivalents(set) {
  for (const group of GENERIC_OBJECT_EQUIVALENTS) {
    if (group.some((term) => set.has(term))) {
      for (const term of group) set.add(term);
    }
  }
  return set;
}

function semanticSet(value) {
  const seq = tokenSequence(value);
  const set = expandGenericObjectEquivalents(new Set(seq));
  // A powerhouse is the generating-building sense of a power station.
  // Expand only from the specific compound to its components; never make
  // a generic station imply a powerhouse.
  if (set.has('powerhouse')) {
    set.add('power');
    set.add('station');
    set.add('powerstation');
  }
  if (set.has('hydroelectric') || set.has('hydroelectricity') || set.has('hydropower')) {
    set.add('hydro');
    set.add('water');
  }
  if (set.has('home')) set.add('house');
  if (set.has('house')) set.add('home');
  if (set.has('reservoir')) set.add('water');
  // A penstock is a pressure pipeline/conduit; expand only from the more
  // specific term so a generic pipeline never implies a hydro penstock.
  if (set.has('penstock')) { set.add('pipeline'); set.add('pipe'); }
  for (let i=0;i+1<seq.length;i++) {
    const joined=seq[i] + seq[i+1];
    if (joined.length >= 5) set.add(joined);
  }
  return set;
}

function subjectEvidenceSet(value) {
  const set = semanticSet(value);
  // Visual-provider metadata often describes a zipper through the action
  // (zip/zipping/unzip/unzipping). Promote that verb family to the depicted
  // fastener noun only when nearby metadata proves a garment/bag/fastener
  // domain. Generic ZIP file/code/archive text must never imply a zipper.
  const FASTENER_CONTEXT = new Set([
    'bag','backpack','jacket','coat','dress','clothing','garment','jean','denim',
    'pocket','wallet','case','shoe','boot','leather','luggage','suitcase',
    'fastener','closure','slider','teeth','pull','puller'
  ]);
  if (
    (set.has('zip') || set.has('unzip')) &&
    [...FASTENER_CONTEXT].some((term) => set.has(term))
  ) {
    set.add('zipper');
  }
  return set;
}

function ratioAgainst(value,set) {
  const ts = terms(value);
  if (!ts.length) return 0;
  let matched = 0;
  for (const t of ts) if (set.has(t)) matched++;
  return matched / ts.length;
}

function average(values) {
  if (!values.length) return 0;
  return values.reduce((a,b) => a+b,0) / values.length;
}

function pexelsPageTitleText(value) {
  const url=String(value || '').trim();
  const match=url.match(/\/\/(?:www\.)?pexels\.com\/(?:photo|video)\/([^/?#]+)/i);
  if (!match) return '';
  return match[1]
    .replace(/-\d+$/u,'')
    .replace(/[-_]+/g,' ')
    .trim();
}

function conceptThreshold(tokenCount) {
  const n=Number(tokenCount || 0);
  if (n <= 1) return 1;
  return Math.ceil(n * 0.60) / n;
}

function scoreCandidate(ctx, metadataText, mediaType, width, height, providerRank, extraReject='', strongMetadataText='', corroborationText='') {
  const metaSet = semanticSet(metadataText);
  const strongSet = semanticSet(strongMetadataText || metadataText);
  const subjectSet = subjectEvidenceSet(strongMetadataText || metadataText);
  const corroborationSet = semanticSet(corroborationText);
  const contextSet = strongSet;
  const querySet = semanticSet(ctx.query);
  const mustShow = Array.isArray(ctx.must_show) ? ctx.must_show.map(String) : [];
  const mustNot = Array.isArray(ctx.must_not_show) ? ctx.must_not_show.map(String) : [];

  const mustRatios = mustShow.map((x) => ratioAgainst(x,subjectSet));
  const mustMeta = average(mustRatios);
  const queryMeta = ratioAgainst(ctx.query,strongSet);
  const intentMeta = ratioAgainst(ctx.visual_intent,metaSet);
  const queryMust = average(mustShow.map((x) => ratioAgainst(x,querySet)));
  const mustProfiles = mustShow.map((value,index) => {
    const allTerms = terms(value);
    return {index,value,allTerms};
  });
  const mustSatisfied = mustProfiles.map((profile,index) =>
    mustRatios[index] >= conceptThreshold(profile.allTerms.length)
  );
  const strongMustCount = mustSatisfied.filter(Boolean).length;
  const requiredMustCount = mustShow.length > 0 ? 1 : 0;
  const domainContext = Array.isArray(ctx.domain_context_terms)
    ? ctx.domain_context_terms.map(String)
    : [];
  const visualDetailTerms = Array.isArray(ctx.visual_detail_terms)
    ? ctx.visual_detail_terms.map(String).filter(Boolean)
    : [];
  const visualDetailTokens = [...new Set(
    visualDetailTerms.flatMap((value) => terms(value))
  )];

  const GENERIC_ANCHORS = new Set([
    'machine','equipment','system','factory','industrial','industry',
    'process','manufactur','material','device','receiver','instrument','unit','apparatus',
    'mouthpart','component','part','chamber','reservoir',
    'pool','basin','drop','droplet','surface','texture','detail',
    'portable','handheld','navigator','navigation',
    'runner','rotor',
    'plant','room','laboratory',
    'lab','cleanroom','tool','work','worker','table','object','result',
    'finish','modern','large','small','electric','electrical','residential'
  ].map(stem));

  const secondaryGenericAnchors = new Set(GENERIC_ANCHORS);

  const MACHINERY_HEADS = new Set([
    'turbine','generator','transformer','engine','motor','pump',
    'compressor','reactor','gearbox','inverter'
  ].map(stem));
  const DOMAIN_SCOPED_FORM_MODIFIERS = [
    'water','hydro','hydraulic','steam','gas','wind','power'
  ].map(stem);
  const rawPrimaryTerms = mustProfiles[0]?.allTerms ?? [];
  const primaryHeadTerm = rawPrimaryTerms.length
    ? rawPrimaryTerms[rawPrimaryTerms.length - 1]
    : '';
  if (domainContext.length && MACHINERY_HEADS.has(primaryHeadTerm)) {
    for (const modifier of DOMAIN_SCOPED_FORM_MODIFIERS) {
      GENERIC_ANCHORS.add(modifier);
    }
  }

  const anchorTerms = terms(mustShow.join(' '))
    .filter((term) => !GENERIC_ANCHORS.has(term));
  const matchedAnchorCount = anchorTerms.filter((term) => subjectSet.has(term)).length;

  const primaryMust = mustProfiles[0] ?? null;
  const primaryMustRatio = primaryMust
    ? Number(mustRatios[primaryMust.index] ?? 0)
    : 0;
  const primaryMustThreshold = primaryMust
    ? conceptThreshold(primaryMust.allTerms.length)
    : 1;
  const primaryDistinctiveTerms = primaryMust
    ? primaryMust.allTerms.filter((term) => !GENERIC_ANCHORS.has(term))
    : [];
  const primaryMatchedDistinctive = primaryDistinctiveTerms
    .filter((term) => subjectSet.has(term)).length;
  // Compound subjects need the same 60% concept coverage as other concepts.
  // Form descriptors above are excluded; one shared word cannot turn an
  // unrelated subject into the requested compound entity.
  const primaryRequiredDistinctive = primaryDistinctiveTerms.length > 0
    ? Math.ceil(primaryDistinctiveTerms.length * 0.60) : 0;
  const primaryDistinctiveCoverage = primaryDistinctiveTerms.length > 0
    ? primaryMatchedDistinctive / primaryDistinctiveTerms.length
    : 0;
  const secondaryContextProfiles = mustProfiles.slice(1)
    .map((profile) => {
      const headTerm = profile.allTerms.length
        ? profile.allTerms[profile.allTerms.length - 1]
        : '';
      return {
        ...profile,
        contextTerms: profile.allTerms.filter(
          (term) =>
            (!secondaryGenericAnchors.has(term) || term === headTerm) &&
            !primaryDistinctiveTerms.includes(term)
        ),
      };
    })
    .filter((profile) => profile.contextTerms.length > 0);
  const secondaryContextSupported =
    secondaryContextProfiles.length === 0 ||
    secondaryContextProfiles.some((profile) => {
      const matched = profile.contextTerms.filter((term) => subjectSet.has(term)).length;
      return matched / profile.contextTerms.length >= conceptThreshold(profile.contextTerms.length);
    });
  const primaryCorroboratedDistinctive = primaryDistinctiveTerms
    .filter((term) => subjectSet.has(term) || corroborationSet.has(term)).length;
  // Pexels page slugs are provider title metadata. They may corroborate one
  // missing subtype term only when the visible-description text already
  // establishes part of the primary subject and independent scene context.
  // The title can never replace a missing visual description.
  const primaryTitleCorroborated =
    primaryDistinctiveTerms.length > 1 &&
    primaryMatchedDistinctive >= 1 &&
    primaryCorroboratedDistinctive >= primaryRequiredDistinctive &&
    secondaryContextSupported &&
    intentMeta >= 0.40;
  const primaryContextSupported =
    primaryDistinctiveTerms.length > 0 &&
    (
      primaryMatchedDistinctive >= primaryRequiredDistinctive ||
      primaryTitleCorroborated
    ) &&
    (
      queryMeta >= 0.20 ||
      intentMeta >= 0.20
    );
  const primarySemanticSatisfied =
    !primaryMust ||
    primaryMust.allTerms.length === 0 ||
    primaryMustRatio >= primaryMustThreshold ||
    primaryContextSupported;

  let rejected = false;
  const reasons = [];

  // Presentation/lifecycle context is not a blanket blacklist. It becomes a
  // contradiction only when the storyboard explicitly asks for machinery in
  // an operating plant/station/facility and the candidate is instead strong-
  // metadata classified as a museum/exhibit/manufacturing/transport scene.
  const intentSet = semanticSet(ctx.visual_intent);
  const operationalSettingTerms = [
    'station','plant','facility','powerhouse','substation','switchyard',
    'operat','operation'
  ].map(stem);
  const nonOperationalContextTerms = [
    'museum','exhibit','exhibition','display','manufactur','transport','showroom',
    'disused','decommissioned','abandoned','inactive','retired'
  ].map(stem);
  const requiresOperationalSetting = operationalSettingTerms.some((term) => intentSet.has(term));
  if (requiresOperationalSetting) {
    const conflicting = nonOperationalContextTerms.filter(
      (term) => contextSet.has(term) && !intentSet.has(term)
    );
    if (conflicting.length) {
      rejected = true;
      reasons.push('conflicting_non_operational_context:' + conflicting.join(','));
    }
  }

  // A storyboard that explicitly places machinery in a plant/station/facility
  // needs positive setting evidence, not merely the absence of a museum/factory
  // contradiction. This prevents a generator+turbine from an aircraft, vehicle,
  // or unrelated standalone machine from satisfying "inside power plant".
  const operationalLocationTerms = [
    'station','plant','facility','powerhouse','substation','switchyard'
  ].map(stem);
  const explicitOperationalLocations = operationalLocationTerms.filter(
    (term) => intentSet.has(term)
  );
  const powerTerm = stem('power');
  const powerFacilityTerms = ['station','plant','powerhouse'].map(stem);
  const powerFacilityIntent =
    intentSet.has(powerTerm) &&
    explicitOperationalLocations.some((term) => powerFacilityTerms.includes(term));
  const powerFacilitySupported =
    contextSet.has(powerTerm) &&
    powerFacilityTerms.some((term) => contextSet.has(term));
  const explicitOperationalLocationSupported =
    explicitOperationalLocations.some((term) => contextSet.has(term));
  const alternativeGridSettingTerms = ['substation','switchyard'].map(stem);
  const alternativeGridSettingSupported =
    explicitOperationalLocations.some(
      (term) =>
        alternativeGridSettingTerms.includes(term) &&
        contextSet.has(term)
    );

  const generationHallSupported =
    contextSet.has(stem('hall')) &&
    (
      contextSet.has(stem('generator')) ||
      contextSet.has(stem('turbine'))
    ) &&
    (
      contextSet.has(stem('station')) ||
      contextSet.has(stem('plant')) ||
      contextSet.has(stem('facility')) ||
      contextSet.has(stem('powerhouse')) ||
      contextSet.has(stem('hydroelectric')) ||
      contextSet.has(stem('steam'))
    );

  const operationalSettingSupported =
    explicitOperationalLocations.length === 0 ||
    (
      powerFacilityIntent
        ? (
            powerFacilitySupported ||
            alternativeGridSettingSupported ||
            generationHallSupported
          )
        : explicitOperationalLocationSupported
    );
  if (
    requiresOperationalSetting &&
    explicitOperationalLocations.length > 0 &&
    !operationalSettingSupported
  ) {
    rejected = true;
    reasons.push('missing_operational_setting_context');
  }

  const domainTokenSatisfied = (wanted) => {
    const target = stem(wanted);
    if (!target) return false;
    if (strongSet.has(target)) return true;
    if (target.length < 4) return false;
    return [...strongSet].some((actual) =>
      actual.length >= 4 &&
      (actual.startsWith(target) || target.startsWith(actual))
    );
  };
  const missingDomain = domainContext.filter(
    (term) => !terms(term).every((token) => domainTokenSatisfied(token))
  );
  if (missingDomain.length) {
    rejected = true;
    reasons.push('missing_storyboard_domain_context:' + missingDomain.join(','));
  }


  const matchedVisualDetailTokens = visualDetailTokens.filter(
    (term) => strongSet.has(term)
  );
  const requiredVisualDetailCount = visualDetailTokens.length > 0
    ? Math.ceil(visualDetailTokens.length * 0.60)
    : 0;
  if (
    visualDetailTokens.length > 0 &&
    matchedVisualDetailTokens.length < requiredVisualDetailCount
  ) {
    rejected = true;
    reasons.push(
      'missing_visual_detail_anchor:' + visualDetailTerms.join(',')
    );
  }


  const forbiddenGenericModifiers = new Set([
    'large','small','modern','old','industrial',
    'electric','electrical','power','equipment','machine','machinery',
    'system','device','unit','apparatus','inside','outside','interior','exterior'
  ].map(stem));
  for (const forbidden of mustNot) {
    const ft = terms(forbidden);
    if (!ft.length) continue;
    const r = ratioAgainst(forbidden,metaSet);
    const head = ft[ft.length - 1];
    const distinctiveModifiers = ft.slice(0,-1).filter(
      (term) => !forbiddenGenericModifiers.has(term)
    );
    // A compound exclusion such as "coal power plant" must not fire merely
    // because generic head/context words ("power plant") overlap.
    const distinctiveSatisfied =
      ft.length === 1 ||
      distinctiveModifiers.length === 0 ||
      distinctiveModifiers.some((term) => metaSet.has(term));
    if (r >= conceptThreshold(ft.length) && distinctiveSatisfied) {
      rejected = true;
      reasons.push('must_not_show:' + forbidden);
    }
  }

  const secondaryMustRatios = mustRatios.slice(1);
  const secondaryMustEvidence = secondaryMustRatios.some((ratio,index) => {
    const profile = mustProfiles[index + 1];
    return ratio >= conceptThreshold(profile?.allTerms?.length || 0);
  });

  const strongQueryEvidence =
    queryMeta >= conceptThreshold(terms(ctx.query).length) &&
    matchedAnchorCount >= 1;

  // The fallback query may be an ambiguous body part/object word. Require
  // independent storyboard context as well when it is supplied, so a query
  // match alone cannot substitute another subject from an unrelated domain.
  if (secondaryContextProfiles.length > 0 &&
      !secondaryContextSupported) {
    rejected = true;
    reasons.push('missing_secondary_subject_context');
  }

  if (
    primaryMust &&
    primaryMust.allTerms.length > 0 &&
    primaryDistinctiveTerms.length > 0 &&
    primaryMatchedDistinctive < primaryRequiredDistinctive &&
    !primaryTitleCorroborated
  ) {
    rejected = true;
    reasons.push('missing_primary_subject_anchor:' + primaryMust.value);
  } else if (
    primaryMust &&
    !primarySemanticSatisfied &&
    !strongQueryEvidence
  ) {
    rejected = true;
    reasons.push('insufficient_primary_subject_coverage:' + primaryMust.value);
  }

  if (
    requiredMustCount > 0 &&
    strongMustCount < requiredMustCount &&
    !strongQueryEvidence &&
    !primarySemanticSatisfied &&
    !secondaryMustEvidence
  ) {
    rejected = true;
    reasons.push('insufficient_must_show_concept_coverage');
  }

  if (queryMeta < 0.25 && intentMeta < 0.20) {
    rejected = true;
    reasons.push('insufficient_query_intent_metadata_match');
  }

  if (
    anchorTerms.length > 0 &&
    matchedAnchorCount < 1
  ) {
    rejected = true;
    reasons.push('missing_distinctive_domain_anchor');
  }

  if (extraReject) {
    rejected = true;
    reasons.push(extraReject);
  }

  const w = Number(width);
  const h = Number(height);
  if (!(w > 0 && h > 0)) {
    rejected = true;
    reasons.push('invalid_dimensions');
  }
  const portraitEnough = w > 0 && h > 0 && (h * 3 >= w * 4);

  let score =
    10 +
    Math.round(35 * mustMeta) +
    Math.round(20 * primaryMustRatio) +
    Math.round(25 * queryMeta) +
    Math.round(15 * intentMeta) +
    Math.round(5 * queryMust) +
    Math.max(0,11 - Number(providerRank || 99));

  if (String(ctx.preferred_media_type) === mediaType) score += 12;

  if (portraitEnough) {
    const aspect = h / w;
    if (aspect >= (16/9)) score += 12;
    else if (aspect >= 1.5) score += 9;
    else score += 6;
  }

  score = Math.max(0,Math.min(100,score));

  return {
    relevance_score: score,
    rejected,
    rejection_reason: reasons.join('; ') || null,
  };
}

const ctx = $('Build Pexels Requests').item.json;
const response = $json ?? {};
const body = response.body && typeof response.body === 'object' ? response.body : {};
const status = Number(response.statusCode ?? response.status ?? 0);

const headers = response.headers && typeof response.headers === 'object' ? response.headers : {};
const rows = status === 200
  ? (
      ctx.endpoint_kind === 'video'
        ? (Array.isArray(body.videos) ? body.videos : [])
        : (Array.isArray(body.photos) ? body.photos : [])
    )
  : [];
const candidates = [];

function chooseVideoFile(files) {
  const variants = (Array.isArray(files) ? files : [])
    .filter((v) =>
      String(v?.file_type || '').toLowerCase() === 'video/mp4' &&
      typeof v?.link === 'string' && v.link.startsWith('https://') &&
      Number(v?.width) > 0 && Number(v?.height) > 0 &&
      (!Number(v?.size) || Number(v.size) <= 80*1024*1024)
    );

  variants.sort((a,b) => {
    const da = Math.abs(Math.max(Number(a.width),Number(a.height)) - 1920);
    const db = Math.abs(Math.max(Number(b.width),Number(b.height)) - 1920);
    if (da !== db) return da-db;
    const qa = String(a.quality || '') === 'hd' ? 0 : 1;
    const qb = String(b.quality || '') === 'hd' ? 0 : 1;
    if (qa !== qb) return qa-qb;
    const pa = Number(a.width)*Number(a.height);
    const pb = Number(b.width)*Number(b.height);
    if (pa !== pb) return pb-pa;
    return Number(a.id || 0)-Number(b.id || 0);
  });
  return variants[0] || null;
}

for (let i=0;i<rows.length;i++) {
  const h = rows[i] || {};
  let mediaType = 'photo';
  let downloadUrl = '';
  let previewUrl = '';
  let width = 0;
  let height = 0;
  let durationMs = null;
  let metadataText = '';

  if (ctx.endpoint_kind === 'video') {
    const v = chooseVideoFile(h.video_files);
    if (!v) continue;
    mediaType = 'video';
    downloadUrl = String(v.link);
    previewUrl = String(h.image || '');
    width = Number(v.width);
    height = Number(v.height);
    durationMs = Math.round(Number(h.duration || 0)*1000);
    if (!(durationMs > 0)) continue;
    metadataText = [
      h.url,
      Array.isArray(h.tags) ? h.tags.join(' ') : h.tags,
      h.user?.name,
    ].filter(Boolean).join(' ');
  } else {
    const src = h.src && typeof h.src === 'object' ? h.src : {};
    downloadUrl = String(src.large2x || src.large || src.original || '');
    previewUrl = String(src.medium || src.small || src.tiny || '');
    width = Number(h.width || 0);
    height = Number(h.height || 0);
    if (!downloadUrl.startsWith('https://') || !(width > 0 && height > 0)) continue;
    metadataText = [h.alt,h.photographer].filter(Boolean).join(' ');
  }

  const strongMetadataText = ctx.endpoint_kind === 'video'
    ? [Array.isArray(h.tags) ? h.tags.join(' ') : h.tags].filter(Boolean).join(' ')
    : String(h.alt || '');
  const corroborationText = ctx.endpoint_kind === 'video'
    ? ''
    : pexelsPageTitleText(h.url);

  const scored = scoreCandidate(
    ctx,
    metadataText,
    mediaType,
    width,
    height,
    i+1,
    ctx.endpoint_kind !== 'video' && !String(h.alt || '').trim()
      ? 'pexels_missing_visual_description'
      : (ctx.endpoint_kind !== 'video' && /\b(illustration|vector|clipart|infographic|poster|typography|graphic design|digital art|3d render)\b/i.test(String(h.alt || ''))
          ? 'pexels_non_photographic_asset' : ''),
    strongMetadataText,
    corroborationText
  );

  candidates.push({
    provider_asset_id:String(h.id),
    provider_rank:i+1,
    media_type:mediaType,
    source_url:String(h.url || ''),
    download_url:downloadUrl,
    preview_url:previewUrl || null,
    author:String(ctx.endpoint_kind === 'video' ? (h.user?.name || '') : (h.photographer || '')) || null,
    author_url:String(ctx.endpoint_kind === 'video' ? (h.user?.url || '') : (h.photographer_url || '')) || null,
    license_name:'Pexels License',
    license_url:'https://www.pexels.com/license/',
    width,
    height,
    duration_ms:durationMs,
    metadata_text:metadataText,
    relevance_score:scored.relevance_score,
    rejected:scored.rejected,
    rejection_reason:scored.rejection_reason,
    metadata:{
      alt:h.alt ?? null,
      avg_color:h.avg_color ?? null,
      tags:h.tags ?? null,
      query:ctx.query,
    },
  });
}

return {json:{
  visual_run_id:ctx.visual_run_id,
  shot_uuid:ctx.shot_uuid,
  provider:'pexels',
  query_index:ctx.query_index,
  query_text:ctx.query,
  provider_query_text:String(ctx.provider_query || ctx.query || '').trim(),
  endpoint_kind:ctx.endpoint_kind,
  http_status:status,
  response_headers:{
    'x-ratelimit-limit':headers['x-ratelimit-limit'] ?? null,
    'x-ratelimit-remaining':headers['x-ratelimit-remaining'] ?? null,
    'x-ratelimit-reset':headers['x-ratelimit-reset'] ?? null,
    'cache-control':headers['cache-control'] ?? null,
    'date':headers.date ?? null,
